edits.new:
syn::Stmt::Item(Item::Static(nested)) => hoisted.push(nested.ident.to_string()),
syn::Stmt::Item(Item::ForeignMod(foreign)) => {
    for item in &foreign.items {
        match item {
            ForeignItem::Fn(decl) => hoisted.push(decl.sig.ident.to_string()),
            ForeignItem::Static(decl) => hoisted.push(decl.ident.to_string()),
            _ => {}
        }
    }
}
